<template><view class="customer-nav"><view v-for="item in items" :key="item.key" class="nav-item" :class="{active:active===item.key}" @tap="go(item)"><view class="nav-symbol">{{item.icon}}</view><text>{{item.label}}</text><view v-if="active===item.key" class="nav-dot" /></view></view></template>
<script>
export default {props:{active:String},data(){return{items:[{key:'home',label:'茶生活',icon:'茶'},{key:'rooms',label:'订茶室',icon:'舍'},{key:'profile',label:'我的',icon:'人'}]}},methods:{go(item){if(item.key!==this.active)uni.redirectTo({url:'/pages/customer/'+item.key})}}}
</script>
<style scoped>.customer-nav{position:fixed;bottom:0;left:0;right:0;z-index:20;display:flex;background:#fffdfa;border-top:1rpx solid #f0e3d6;padding:14rpx 24rpx calc(14rpx + env(safe-area-inset-bottom));box-shadow:0 -8rpx 40rpx rgba(126,54,25,.045)}.nav-item{flex:1;display:flex;flex-direction:column;align-items:center;gap:4rpx;color:#8d8073;position:relative;padding:4rpx;font-size:21rpx}.nav-symbol{font-family:serif;font-size:33rpx;line-height:40rpx}.active{color:#b5362d;font-weight:600}.nav-dot{position:absolute;width:6rpx;height:6rpx;right:calc(50% - 28rpx);top:8rpx;background:#c33c2f;border-radius:50%}</style>
